INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "石锷", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：石锷。", "biography": null, "status": "draft", "id": "7456c285-ede8-5eb6-b772-7e183ab6e8ee"}, {"name": "毕师铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：毕师铎。", "biography": null, "status": "draft", "id": "f1541150-4966-5c04-9879-060cf391f2c2"}, {"name": "秦彦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：秦彦。", "biography": null, "status": "draft", "id": "720ca49a-19c0-563d-9b63-48f1e8e448f8"}, {"name": "秦稠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：秦稠。", "biography": null, "status": "draft", "id": "b8191a00-f8fa-5e6d-96ca-f3f31dd1f87e"}, {"name": "吕用之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的吕用之，在此段中为被指控者。", "biography": null, "status": "draft", "id": "cd08ae2a-9825-5636-a942-312bb29aed61"}, {"name": "高杰", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：高杰。", "biography": null, "status": "draft", "id": "c31d3cc1-f8d0-5d72-858b-f632f2b5ff73"}, {"name": "梁缵", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：梁缵。", "biography": null, "status": "draft", "id": "985dc03d-8a3e-5c94-8da8-0d0f79191458"}, {"name": "郑汉章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：郑汉章。", "biography": null, "status": "draft", "id": "6627883e-83a2-5c78-b77d-a62093d2195c"}, {"name": "申及", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：申及。", "biography": null, "status": "draft", "id": "8b4ba64f-1533-5ec7-9d13-c7636cdd1d74"}, {"name": "张雄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张雄。", "biography": null, "status": "draft", "id": "c143e925-2fd8-5be6-abed-b89d550f0724"}, {"name": "孙约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：孙约。", "biography": null, "status": "draft", "id": "b7f09374-86d0-5eaa-8d03-60d8fef12186"}, {"name": "唐宏", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：唐宏。", "biography": null, "status": "draft", "id": "578772db-7adc-59db-9636-e56aba3f1b84"}, {"name": "诸葛殷", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：诸葛殷。", "biography": null, "status": "draft", "id": "fafc93ce-fe25-550c-a1d7-9680812979bb"}, {"name": "郑杞", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑杞。", "biography": null, "status": "draft", "id": "56a0d2ee-e0d0-5ab8-8973-70182a87da27"}, {"name": "高霸", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：高霸。", "biography": null, "status": "draft", "id": "64514634-2a39-5304-9e5c-ffda4859587b"}, {"name": "卢瑭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：卢瑭。", "biography": null, "status": "draft", "id": "f261eeea-b1c9-5d4b-8c98-731e7c6353a9"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "张晊", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：张晊。", "biography": null, "status": "draft", "id": "4c26e1dc-5a81-51f0-b046-cee75fe25e88"}]'::jsonb)
