INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "高骈遣石锷劝毕师铎", "start_year": 887, "end_year": 887, "time_original": "光启三年四月；具体日未载", "dynasty": "唐", "description": "高骈遣石锷带毕师铎幼子、其母书信及高骈的解释到扬子劝说。毕师铎送子返，要求先杀“吕、张”，愿以妻子为质；高骈收毕师铎母、妻、子置于使院。", "phases": [], "location_name": "扬子、广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7ee696c9-1e49-5a39-b10a-2cdf9eeb92c0"}, {"title": "秦彦遣秦稠助毕师铎", "start_year": 887, "end_year": 887, "time_original": "光启三年四月辛酉", "dynasty": "唐", "description": "秦彦遣秦稠率兵至扬子援助毕师铎。", "phases": [], "location_name": "扬子", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d0474906-f8af-5cf6-bdae-312a1295a62f"}, {"title": "宣州军连日攻广陵", "start_year": 887, "end_year": 887, "time_original": "光启三年四月壬戌至甲子", "dynasty": "唐", "description": "宣州军壬戌攻南门未克，癸亥攻罗城东南隅几次险些破城；甲子罗城西南隅有守者焚守具响应毕师铎，毕师铎毁城入兵。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2f9bd136-276b-5a07-b634-831bc616dbc5"}, {"title": "吕用之战后三桥北逃离广陵", "start_year": 887, "end_year": 887, "time_original": "光启三年四月甲子", "dynasty": "唐", "description": "吕用之率军在三桥北与毕师铎军战；高杰从子城出兵拟擒吕用之交给毕师铎，吕用之遂开参佐门北走。", "phases": [], "location_name": "广陵三桥北、参佐门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c814c3f2-a457-5a06-8787-4f75eaf5d122"}, {"title": "高骈命梁缵守子城", "start_year": 887, "end_year": 887, "time_original": "光启三年四月甲子", "dynasty": "唐", "description": "吕用之北走后，高骈召梁缵率昭义军百余人守子城。", "phases": [], "location_name": "广陵子城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fdb1878e-a39b-5b4d-9c1d-a88c0ad753ef"}, {"title": "毕师铎入城掠夺并获高骈任命", "start_year": 887, "end_year": 887, "time_original": "光启三年四月乙丑", "dynasty": "唐", "description": "毕师铎纵兵大掠。高骈撤除戒备与其相见，署毕师铎为节度副使、行军司马，加左仆射；郑汉章等人也获得迁官。", "phases": [], "location_name": "广陵延和阁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "30ce0d87-e9f8-5c2a-8dbf-2fcdf94df4dd"}, {"title": "申及劝高骈夜逃而未获采纳", "start_year": 887, "end_year": 887, "time_original": "毕师铎入城后；具体日未载", "dynasty": "唐", "description": "申及建议高骈夜出城门、调诸镇兵再取府城；高骈犹豫未从。申及惧言泄而藏匿，张雄抵东塘时前往投奔。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cc735ed8-70ee-5aa7-b673-0f8deec6e841"}, {"title": "毕师铎守广陵诸门并诛吕用之亲党", "start_year": 887, "end_year": 887, "time_original": "光启三年四月丙寅", "dynasty": "唐", "description": "毕师铎分兵守城门，搜捕并杀吕用之亲党，自己入居使院。秦稠以宣州军守使宅及仓库。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b43d6a2b-cc43-51b4-8dee-ab88a8fa6712"}, {"title": "高骈请解任，毕师铎兼判府事", "start_year": 887, "end_year": 887, "time_original": "光启三年四月丙寅", "dynasty": "唐", "description": "高骈以公文请求解除所任，由毕师铎兼判府事。毕师铎遣孙约赴宣城催秦彦过江。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4d75e0f5-4347-57a3-9515-34ff59748d75"}, {"title": "毕师铎拒绝停止迎秦彦的劝告", "start_year": 887, "end_year": 887, "time_original": "光启三年四月丙寅后", "dynasty": "唐", "description": "一名未具名者劝毕师铎继续奉高骈、总兵权并阻秦彦过江；毕师铎不接受，次日告知郑汉章。郑汉章赞其为智士，搜寻而不得。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "789eca33-b495-54f6-a77a-5ddc30a5f8c9"}, {"title": "高骈被迁居南第并受监禁", "start_year": 887, "end_year": 887, "time_original": "光启三年四月戊辰", "dynasty": "唐", "description": "高骈迁家至南第，毕师铎以甲士百人名义上护卫，实际将其拘禁。", "phases": [], "location_name": "广陵南第", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52472f06-4e18-5786-b9e9-a87f4fde9610"}, {"title": "宣州军焚进奉楼", "start_year": 887, "end_year": 887, "time_original": "光启三年四月戊辰", "dynasty": "唐", "description": "宣州军因所求未得，焚进奉楼，楼中财物被焚。", "phases": [], "location_name": "广陵进奉楼", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "50a87049-8162-58c9-9b81-94b0a2eec6db"}, {"title": "毕师铎府厅视事并迁高骈东第", "start_year": 887, "end_year": 887, "time_original": "光启三年四月己巳", "dynasty": "唐", "description": "毕师铎在府厅视事，保留不掌兵权官吏原职，又将高骈迁至东第。", "phases": [], "location_name": "广陵府厅、东第", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c9fe0fe9-9b58-5895-b28c-6ea74deea157"}, {"title": "毕师铎任唐宏禁广陵军掠", "start_year": 887, "end_year": 887, "time_original": "光启三年四月己巳", "dynasty": "唐", "description": "广陵陷落后诸军昼夜劫掠，高骈所积财物亦被抢走；毕师铎至此任唐宏为静街使，命其禁止劫掠。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "672062ac-7ff9-570e-ac56-12bdb5c541a1"}, {"title": "诸葛殷被杖杀", "start_year": 887, "end_year": 887, "time_original": "光启三年四月庚午", "dynasty": "唐", "description": "诸葛殷被捕后杖杀，遗体又遭怨家与众人毁辱。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cbe19433-ee55-5270-bd25-57ab8031b30f"}, {"title": "郑杞转投毕师铎后被高霸杀害", "start_year": 887, "end_year": 887, "time_original": "吕用之败后至光启三年四月庚午前后", "dynasty": "唐", "description": "吕用之败后郑杞先投毕师铎，获署知海陵监事；其后暗记高霸得失并报告毕师铎，高霸取得书信后酷刑杀郑杞。", "phases": [], "location_name": "海陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0ff3a3e1-7ceb-544c-a88b-afa3e791dd73"}, {"title": "朱全忠袭击卢瑭万胜营", "start_year": 887, "end_year": 887, "time_original": "光启三年四月；具体日未载", "dynasty": "唐", "description": "卢瑭屯万胜截汴州运路；朱全忠乘雾袭击其营，卢瑭军败。", "phases": [], "location_name": "万胜、汴水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "69db4a2c-8a95-56d1-bb9f-279d48701b55"}, {"title": "朱全忠再攻张晊赤冈营", "start_year": 887, "end_year": 887, "time_original": "袭卢瑭营后；具体日未载", "dynasty": "唐", "description": "蔡兵移往张晊驻守的赤冈，朱全忠再攻；蔡军惊惧，朱全忠随后返大梁休兵。", "phases": [], "location_name": "赤冈、大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2bf0028b-c5d9-564d-ab39-9300ecee4169"}, {"title": "高骈以金贿守者", "start_year": 887, "end_year": 887, "time_original": "光启三年四月辛未", "dynasty": "唐", "description": "高骈暗中给看守者黄金，毕师铎获知。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7ce159b5-4b73-58a8-9451-38bf6bcc6587"}, {"title": "毕师铎幽禁高骈家人", "start_year": 887, "end_year": 887, "time_original": "光启三年四月壬午", "dynasty": "唐", "description": "毕师铎再次迎高骈入道院，并将高氏子弟、甥侄十余人一同幽禁。", "phases": [], "location_name": "广陵道院", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1c587b72-511b-5394-9259-d676faa9b5e0"}]'::jsonb)
