SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "高骈遣石锷带毕师铎幼子、其母书信及高骈的解释到扬子劝说。毕师铎送子返，要求先杀“吕、张”，愿以妻子为质；高骈收毕师铎母、妻、子置于使院。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p009·原文件第14行", "note": "原文：骈遣大将石锷以师鐸幼子及其母书并骈委曲至扬子谕师鐸，师鐸遽遣其子还，曰：“令公但斩吕、张以示师鐸，师鐸不敢负恩，愿以妻子为质。”骈恐用之屠其家，收师鐸母妻子置使院。；核对说明：原文仅称“吕、张”，此处不擅自展开张氏身份；“恐用之屠其家”是高骈的忧虑。", "status": "draft", "id": "6c0beca7-cfe4-55b4-a397-51d8cbee761a", "subject_id": "7ee696c9-1e49-5a39-b10a-2cdf9eeb92c0", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "光启三年四月；具体日未载", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p009·原文件第14行", "note": "原文：骈遣大将石锷以师鐸幼子及其母书并骈委曲至扬子谕师鐸，师鐸遽遣其子还，曰：“令公但斩吕、张以示师鐸，师鐸不敢负恩，愿以妻子为质。”骈恐用之屠其家，收师鐸母妻子置使院。；核对说明：原文仅称“吕、张”，此处不擅自展开张氏身份；“恐用之屠其家”是高骈的忧虑。", "status": "draft", "id": "e9bd8f2e-67fe-5226-ac9c-18c1434dcb8d", "subject_id": "7ee696c9-1e49-5a39-b10a-2cdf9eeb92c0", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记高骈：遣使及收置家眷者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p009·原文件第14行", "note": "原文：骈遣大将石锷以师鐸幼子及其母书并骈委曲至扬子谕师鐸，师鐸遽遣其子还，曰：“令公但斩吕、张以示师鐸，师鐸不敢负恩，愿以妻子为质。”骈恐用之屠其家，收师鐸母妻子置使院。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "a388a04f-a512-53c5-9494-43f7479d8425", "subject_id": "c4d5b35a-b520-57df-87da-baff9480b7e4", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "高骈：遣使及收置家眷者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p009·原文件第14行", "note": "原文：骈遣大将石锷以师鐸幼子及其母书并骈委曲至扬子谕师鐸，师鐸遽遣其子还，曰：“令公但斩吕、张以示师鐸，师鐸不敢负恩，愿以妻子为质。”骈恐用之屠其家，收师鐸母妻子置使院。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "c0190013-0170-56dc-9e1b-47d95e7a4b6c", "subject_id": "4b41a703-4220-5121-a2d5-310066cb41e9", "source_id": "9512f2c9-5083